        questions = B.spread(listOf(
            // Identity, governance and monitoring: logging and monitoring
            B.q("sa-m4-1", "sa-monitoring", "Logs from European resources must be stored only in Europe, and logs from Australian resources only in Australia, while central operators can still query both. What workspace design do you recommend?", listOf("One Log Analytics workspace in Europe for everything", "A workspace in each geography, with operators granted access to both and querying across them", "No workspaces; keep logs in each resource", "One workspace per resource"), setOf(1), "Log data is stored in the region of the workspace. A workspace in each geography keeps data where the law requires, and one KQL query can still read several workspaces for operators who have access to both.",
                scenario = "Lyrebird Health runs its Android telehealth app in West Europe and Australia East. Health data laws in both places say logs that mention patients must not leave the country or region.",
                whyWrong = mapOf(
                    0 to "A single European workspace would send Australian logs out of Australia.",
                    2 to "Most resources keep little or nothing by themselves, and nothing could be queried centrally.",
                    3 to "A workspace per resource scatters logs and makes queries and access far harder.",
                ),
            ),
            B.q("sa-m4-2", "sa-monitoring", "Operators want one interactive report that combines metrics and log queries, with drop-downs to pick a region and time range, shared with the whole team. What do you recommend?", listOf("Azure Monitor workbooks", "An activity log export", "A metric alert", "Azure Advisor"), setOf(0), "Workbooks are interactive reports in the Azure portal. They mix text, log queries, metrics and parameters such as drop-downs, and they can be saved and shared with the team.",
