            B.q("sa-m4-3", "sa-monitoring", "The security operations team needs a cloud SIEM over the existing Log Analytics data that correlates threats across sources and can respond automatically, for example by disabling a user. What do you recommend?", listOf("Microsoft Sentinel, with playbooks for automated response", "Azure Monitor metric alerts", "Application Insights", "Azure Service Health"), setOf(0), "Microsoft Sentinel is a cloud SIEM (security information and event management) that runs on a Log Analytics workspace. It correlates signals into incidents, and playbooks, built on Logic Apps, can respond automatically.",
                scenario = "Hartfield Bank already sends sign-in logs and firewall logs to a workspace. Its new security team for the Android banking app has no SIEM and wants one without new servers.",
                whyWrong = mapOf(
