            // Identity
            B.q("sa-m4-5", "sa-identity", "After a merger, users in the parent tenant must appear automatically in the subsidiary's tenant, and leave it when they leave the parent, so they can use its apps. What do you recommend?", listOf("Invite each user by hand as a B2B guest", "Cross-tenant synchronization from the parent tenant to the subsidiary's tenant", "Merge both tenants into one immediately", "Microsoft Entra Connect between the two tenants"), setOf(1), "Cross-tenant synchronization automatically creates, updates and removes B2B users in another tenant of the same organisation. Leavers in the source tenant are removed in the target without manual work.",
                scenario = "Corvid Group bought Pipit Studios, which keeps its own Microsoft Entra tenant for now. Corvid's staff need Pipit's internal apps, including its Android design-review app.",
                whyWrong = mapOf(
                    0 to "Manual invitations do not scale and leavers are easily missed.",
                    2 to "Merging tenants is a long project, not a quick fix for access.",
                    3 to "Entra Connect syncs on-premises Active Directory to a tenant, not one tenant to another.",
