            B.q("sa-m4-8", "sa-identity", "Customers of the Android app must be able to sign up with their Google or Facebook accounts, as well as with email. What do you configure?", listOf("Add Google and Facebook as identity providers in a Microsoft Entra External ID external tenant and include them in the sign-up user flow", "Create a workforce account for each customer", "Store customers' Google passwords in the app's database", "Invite customers as B2B guests in the workforce tenant"), setOf(0), "In an External ID external tenant, social identity providers such as Google and Facebook are added and then switched on in a sign-up and sign-in user flow. Customers pick the account they already have.",
                scenario = "Petalpost is launching an Android flower delivery app. Marketing found that half of customers abandon sign-up when they have to create yet another password.",
