            B.q("sa-m4-11", "sa-authorization", "The Key Vault must be reachable only from the company's VNets through a private address, never from the internet. What do you configure? Select two.", listOf("A private endpoint for the vault in the hub VNet, with its private DNS zone", "Disable public network access on the vault", "An access policy for the internet", "A resource lock on the vault"), setOf(0, 1), "A private endpoint gives the vault a private IP address inside the VNet, and a private DNS zone makes its name resolve to that address. Disabling public network access closes the internet path altogether.",
                scenario = "Medway Pharmaceuticals keeps signing keys for its Android app releases in Key Vault. Security found the vault's public endpoint reachable from anywhere.",
