            B.q("sa-m4-12", "sa-authorization", "Office staff must open an Azure Files share with their on-premises Active Directory accounts, keeping the existing folder permissions. What do you configure? Select two.", listOf("Active Directory Domain Services authentication on the storage account", "Share-level permissions through roles such as Storage File Data SMB Share Contributor", "A storage account key mapped as a network drive on every PC", "Anonymous public access to the share"), setOf(0, 1), "With AD DS authentication, the storage account joins the on-premises domain and users sign in with their AD accounts. Share-level Azure roles decide who can reach the share, and the existing Windows (NTFS) folder permissions still apply inside it.",
                scenario = "Calloway Surveyors moved its file server to Azure Files. The same files are uploaded by its Android site-survey app, and staff must keep their usual sign-in and folder permissions.",
                whyWrong = mapOf(
