            // Governance
            B.q("sa-m4-13", "sa-governance", "Which subscription and resource group design do you recommend for a product's production and non-production environments? Select two.", listOf("Separate subscriptions for production and non-production", "Resource groups that hold resources sharing the same lifecycle, deployed and deleted together", "Everything in one resource group per company", "One subscription per resource"), setOf(0, 1), "Separate subscriptions keep production apart, with its own access, policies, quotas and costs. Within a subscription, resource groups should hold resources that share a lifecycle, so they are deployed, managed and deleted together.",
                scenario = "Driftwood Media is setting up Azure for its Android podcast app. Last year, a developer testing a script in a shared subscription deleted production storage.",
                whyWrong = mapOf(
