            B.q("sa-m4-14", "sa-governance", "Auditors want a list of every storage account across 120 subscriptions that allows public blob access, within seconds and without a script per subscription. What do you recommend?", listOf("An Azure Resource Graph query", "The activity log", "Azure Advisor", "A resource lock report"), setOf(0), "Azure Resource Graph lets you query resource properties across all subscriptions you can see, with KQL, and answers in seconds. It suits inventory and configuration questions at scale.",
                scenario = "Oakmoor Group's platform team owns 120 subscriptions, including those behind its Android apps. Auditors arrive tomorrow and want the list.",
                whyWrong = mapOf(
