            // Data: relational
            B.q("sa-m4-17", "sa-relational", "Columns must stay encrypted from administrators, yet the app needs searches such as LIKE and range comparisons on them. What do you recommend?", listOf("Always Encrypted with secure enclaves", "Always Encrypted with deterministic encryption only", "Dynamic data masking", "Transparent data encryption"), setOf(0), "Always Encrypted keeps data encrypted from the database engine and its administrators. With secure enclaves, a protected area of memory, the engine can also run pattern matching and range comparisons on encrypted columns.",
                scenario = "Ashby Legal's Android case app searches client names stored in Azure SQL. The firm must keep the names unreadable to DBAs and to Microsoft, but searches by partial name are essential.",
                whyWrong = mapOf(
