            B.q("sa-m4-18", "sa-relational", "The same index maintenance script must run every night on 400 Azure SQL databases, tracked centrally. What do you recommend?", listOf("Elastic jobs", "SQL Server Agent on each database", "A laptop running the script in a loop", "Azure Data Factory copy activities"), setOf(0), "Elastic jobs run T-SQL scripts on a schedule across many Azure SQL databases, targeted by group, with retries and a history of each run. Azure SQL Database has no SQL Server Agent of its own.",
                scenario = "Wrenbury runs a database per customer for its Android salon-booking app. Index maintenance is done by hand and often skipped.",
