            B.q("sa-m4-21", "sa-relational", "One tenant database cannot hold all tenants as the app grows to millions of users, and each request belongs to one tenant. How do you scale out the data in Azure SQL Database?", listOf("Shard tenants across many databases, using a shard map from the Elastic Database client library to route requests", "Scale the single database up forever", "Store everything in one table with no index", "Use a larger page size"), setOf(0), "Sharding spreads tenants over many databases. A shard map, kept by the Elastic Database client library, records which database holds each tenant, so the app sends each request to the right one.",
                scenario = "Quillon's Android budgeting app has grown from 10,000 to 2 million users. Its single database is near the top tier, and every request knows its tenant ID.",
