            B.q("sa-m4-26", "sa-nonrelational", "An existing app built on Apache Cassandra must move to a managed Azure service while keeping its CQL queries and drivers. What do you recommend?", listOf("Azure Cosmos DB for Apache Cassandra", "Azure Cosmos DB for NoSQL", "Azure SQL Database", "Azure Table storage"), setOf(0), "Azure Cosmos DB for Apache Cassandra speaks the Cassandra wire protocol, so apps keep their CQL (Cassandra Query Language) queries and drivers, while Azure handles scaling and replication.",
                scenario = "Stormlight's Android weather app stores forecasts in a Cassandra cluster the team is tired of running.",
