            // Data integration
            B.q("sa-m4-27", "sa-data-integration", "The self-hosted integration runtime that reaches on-premises databases is a single point of failure, and it is overloaded at night. What do you recommend?", listOf("Install the self-hosted integration runtime on a second node and register it to the same runtime", "Replace it with the Azure integration runtime", "Run the pipelines during the day", "Move the databases to Azure first"), setOf(0), "A self-hosted integration runtime can have up to four nodes. Extra nodes give high availability, so jobs keep running if one machine fails, and share the load.",
                scenario = "Copperbeech Retail's nightly pipelines copy sales from on-premises SQL Server into the lake for its Android loyalty app. Last month the one runtime server rebooted and the reports were not ready.",
