            B.q("sa-m4-28", "sa-data-integration", "Access to tables, columns and files in Azure Databricks must be governed centrally across workspaces, with lineage and auditing. What do you recommend?", listOf("Unity Catalog", "Storage account keys shared with each team", "One workspace per user", "Folder names that describe who may read them"), setOf(0), "Unity Catalog is Databricks' central governance layer. It defines permissions on catalogs, tables, columns and files once for many workspaces, and records lineage and audit logs.",
                scenario = "Midhurst Bank has Databricks workspaces for risk, marketing and the Android app team. Each one manages access in its own way, and auditors cannot see who can read what.",
