            // Business continuity: backup and disaster recovery
            B.q("sa-m4-31", "sa-backup-dr", "A faulty batch job overwrote thousands of block blobs in a container this morning. You must roll the container back to how it was at 06:00. What should have been enabled, and used now?", listOf("Point-in-time restore for block blobs, with versioning, change feed and soft delete", "Geo-redundant storage", "A CanNotDelete lock", "Immutable storage"), setOf(0), "Point-in-time restore returns block blobs in chosen containers to their state at an earlier moment. It relies on blob versioning, the change feed and soft delete being turned on.",
                scenario = "Wavebreak Surf's Android app reads surf spot data from Blob Storage. A batch job wrote bad files over the whole container at 07:30.",
                whyWrong = mapOf(
