                    2 to "Front Door is for web traffic from the internet.",
                    3 to "A NAT gateway handles outbound internet traffic.",
                ),
            ),
            B.q("sa-m4-60", "sa-network-optimize", "A third-party firewall appliance must inspect traffic to public-facing load balancers, inserted transparently, without changing routes or the apps. What do you recommend?", listOf("A Gateway Load Balancer chained to the public Standard Load Balancer's front end", "A user-defined route on every subnet", "Azure DNS", "A NAT gateway"), setOf(0), "Gateway Load Balancer lets you chain network virtual appliances, such as third-party firewalls, in front of a Standard Load Balancer or VM public IP. Traffic flows through the appliances transparently, with no route changes.",
                scenario = "Wardlow Bank's security team insists on its usual third-party firewall in front of the public API for its Android app. The app team does not want routing changes.",
                whyWrong = mapOf(
                    1 to "Route tables are the routing changes the app team wants to avoid.",
